const ALPHA = [
  ['CH<sub>3</sub>CH<sub>2</sub><sup>+</sup>', [3]], ['CH<sub>3</sub>CH<sub>2</sub>CH<sub>2</sub><sup>+</sup>', [2]], ['(CH<sub>3</sub>)<sub>2</sub>CH<sup>+</sup>', [3, 3]], ['(CH<sub>3</sub>)<sub>3</sub>C<sup>+</sup>', [3, 3, 3]],
  ['(CH<sub>3</sub>CH<sub>2</sub>)<sub>2</sub>CH<sup>+</sup>', [2, 2]], ['(CH<sub>3</sub>)<sub>2</sub>C<sup>+</sup>CH<sub>2</sub>CH<sub>3</sub>', [3, 3, 2]], ['(CH<sub>3</sub>CH<sub>2</sub>)<sub>3</sub>C<sup>+</sup>', [2, 2, 2]],
  ['propene, CH<sub>3</sub>CH=CH<sub>2</sub>', [3]], ['but-2-ene, CH<sub>3</sub>CH=CHCH<sub>3</sub>', [3, 3]], ['2-methylpropene, (CH<sub>3</sub>)<sub>2</sub>C=CH<sub>2</sub>', [3, 3]], ['2,3-dimethylbut-2-ene, (CH<sub>3</sub>)<sub>2</sub>C=C(CH<sub>3</sub>)<sub>2</sub>', [3, 3, 3, 3]],
  ['toluene, C<sub>6</sub>H<sub>5</sub>CH<sub>3</sub> (hyperconjugation into the ring)', [3]], ['ethylbenzene, C<sub>6</sub>H<sub>5</sub>CH<sub>2</sub>CH<sub>3</sub>', [2]], ['cumene, C<sub>6</sub>H<sub>5</sub>CH(CH<sub>3</sub>)<sub>2</sub>', [1]],
];
const COMPOUNDS = [['C<sub>2</sub>H<sub>4</sub>O<sub>2</sub>', 2, 4, 2], ['C<sub>3</sub>H<sub>6</sub>O', 3, 6, 1], ['C<sub>4</sub>H<sub>8</sub>O<sub>2</sub>', 4, 8, 2], ['C<sub>6</sub>H<sub>12</sub>O<sub>6</sub>', 6, 12, 6], ['C<sub>6</sub>H<sub>6</sub>O', 6, 6, 1], ['C<sub>7</sub>H<sub>6</sub>O<sub>2</sub>', 7, 6, 2], ['C<sub>8</sub>H<sub>8</sub>O<sub>2</sub>', 8, 8, 2], ['C<sub>2</sub>H<sub>6</sub>O', 2, 6, 1], ['C<sub>3</sub>H<sub>8</sub>O<sub>3</sub>', 3, 8, 3], ['C<sub>4</sub>H<sub>10</sub>O', 4, 10, 1], ['C<sub>6</sub>H<sub>12</sub>O<sub>2</sub>', 6, 12, 2], ['C<sub>5</sub>H<sub>10</sub>O', 5, 10, 1], ['C<sub>9</sub>H<sub>8</sub>O<sub>4</sub>', 9, 8, 4]];
const geoCount = (n) => { let k = 0; const seen = new Set(); for (let m = 0; m < 1 << n; m++) { const a = []; for (let i = 0; i < n; i++) a.push((m >> i) & 1); const r = [...a].reverse(); const key = Math.min(parseInt(a.join(''), 2), parseInt(r.join(''), 2)); if (!seen.has(key)) { seen.add(key); k++; } } return k; };
const chiralCount = (n) => { const seen = new Set(); for (let m = 0; m < 1 << n; m++) { const a = []; for (let i = 0; i < n; i++) a.push((m >> i) & 1); const r = a.map((x) => 1 - x).reverse(); const key = Math.min(parseInt(a.join(''), 2), parseInt(r.join(''), 2)); seen.add(key); } return seen.size; };
const RFLIST = ['dye A', 'amino acid spot', 'plant pigment', 'impurity spot'];

const GENS = [
  { id: 'go-g01', type: 'nat', level: 2, exams: EX[2], sub: 'degree of unsaturation',
    make(rng) {
      const c = int(rng, 4, 12), z = int(rng, 0, 2), w = int(rng, 0, 2), d = int(rng, 1, Math.min(6, c - 1)); const y = 2 * c + 2 + z - w - 2 * d;
      const hal = w ? `Cl<sub>${w === 1 ? '' : w}</sub>`.replace('<sub></sub>', '') : ''; const nit = z ? `N${z > 1 ? `<sub>${z}</sub>` : ''}` : '';
      const fm = `C<sub>${c}</sub>H<sub>${y}</sub>${nit}${hal}`;
      return { q: `The degree of unsaturation (rings + double bonds + 2 &times; triple bonds) of ${fm} is`, answer: d, tol: 0, c, y, z, w,
        sol: `<p>DoU = (2C + 2 + N &minus; H &minus; X)/2 = (2 &times; ${c} + 2 + ${z} &minus; ${y} &minus; ${w})/2 = ${2 * c + 2 + z - y - w}/2 = <b>${d}</b>.</p><p>Halogens count like hydrogen; nitrogen adds 1 to the hydrogen count of the saturated formula.</p>` };
    }, verify: (p) => (2 * p.c + 2 + p.z - p.y - p.w) / 2 },
  { id: 'go-g02', type: 'nat', level: 3, exams: EX[3], sub: 'Dumas method',
    make(rng) {
      const V = pick(rng, 20, 70, 0.5), w = pick(rng, 0.2, 0.6, 0.05); const a = 28 * V * 100 / (22400 * w);
      return { q: `In the Dumas method, ${w} g of an organic compound gave ${V} mL of nitrogen measured at STP. Find the percentage of nitrogen.`, answer: +a.toFixed(2), tol: 0.05, unit: '%', V, w,
        sol: `<p>22400 mL of N<sub>2</sub> at STP weighs 28 g, so ${V} mL weighs 28 &times; ${V}/22400 = ${(28 * V / 22400).toFixed(4)} g.</p><p>%N = ${(28 * V / 22400).toFixed(4)}/${w} &times; 100 = <b>${a.toFixed(2)} %</b>.</p>` };
    }, verify: (p) => (p.V / 22400) * 28 / p.w * 100 },
  { id: 'go-g03', type: 'nat', level: 4, exams: EX[4], sub: 'Dumas method',
    make(rng) {
      const w = pick(rng, 0.3, 0.6, 0.05), V = pick(rng, 30, 60, 1), P = pick(rng, 745, 765, 5), aq = pick(rng, 14, 18, 1), T = pick(rng, 15, 30, 5);
      const V0 = (P - aq) * V * 273 / (760 * (273 + T)); const a = 28 * V0 * 100 / (22400 * w);
      return { q: `${w} g of an organic compound gave ${V} mL of N<sub>2</sub> collected over water at ${T} &deg;C and a total pressure of ${P} mm Hg. The aqueous tension at ${T} &deg;C is ${aq} mm Hg. Find the percentage of nitrogen (STP: 273 K, 760 mm Hg).`, answer: +a.toFixed(2), tol: 0.1, unit: '%', w, V, P, aq, T,
        sol: `<p>Pressure of dry N<sub>2</sub> = ${P} &minus; ${aq} = ${P - aq} mm Hg.</p><p>Volume at STP: V<sub>0</sub> = (${P - aq} &times; ${V} &times; 273)/(760 &times; ${273 + T}) = ${V0.toFixed(2)} mL.</p><p>%N = 28 &times; ${V0.toFixed(2)} &times; 100/(22400 &times; ${w}) = <b>${a.toFixed(2)} %</b>.</p>`, trap: 'Subtract the aqueous tension before converting to STP.' };
    }, verify: (p) => 28 * 100 / (22400 * p.w) * ((p.P - p.aq) / 760) * (273 / (273 + p.T)) * p.V },
  { id: 'go-g04', type: 'nat', level: 3, exams: EX[3], sub: 'Kjeldahl method',
    make(rng) {
      const w = pick(rng, 0.3, 0.6, 0.05), N1 = choose(rng, [0.1, 0.2, 0.5]), V1 = pick(rng, 20, 50, 5), N2 = choose(rng, [0.1, 0.2, 0.5]);
      const used = Math.max(0.2, N1 * V1 * (0.5 + 0.4 * rng())); const V2 = +((N1 * V1 - used) / N2).toFixed(1); const meq = N1 * V1 - N2 * V2;
      const a = 1.4 * meq / w;
      return { q: `In a Kjeldahl estimation, ${w} g of a compound gave ammonia that was absorbed in ${V1} mL of ${N1} N H<sub>2</sub>SO<sub>4</sub>. The excess acid needed ${V2} mL of ${N2} N NaOH. Find the percentage of nitrogen.`, answer: +a.toFixed(2), tol: 0.1, unit: '%', w, N1, V1, N2, V2,
        sol: `<p>Acid taken = ${N1} &times; ${V1} = ${(N1 * V1).toFixed(2)} meq. Excess = ${N2} &times; ${V2} = ${(N2 * V2).toFixed(2)} meq.</p><p>Acid used by NH<sub>3</sub> = ${meq.toFixed(2)} meq = meq of NH<sub>3</sub> = meq of N. Mass of N = ${meq.toFixed(2)} &times; 14 mg = ${(meq * 14).toFixed(1)} mg.</p><p>%N = 1.4 &times; ${meq.toFixed(2)} / ${w} = <b>${a.toFixed(2)} %</b>.</p>` };
    }, verify: (p) => (p.N1 * p.V1 - p.N2 * p.V2) * 14 / 1000 / p.w * 100 },
  { id: 'go-g05', type: 'nat', level: 3, exams: EX[3], sub: 'Carius method (halogen)',
    make(rng) {
      const X = choose(rng, ['Cl', 'Br', 'I']), [at, mw] = AGX[X]; const w = pick(rng, 0.2, 0.5, 0.05), m = pick(rng, 0.2, 0.6, 0.01);
      const a = at / mw * m / w * 100;
      return { q: `In a Carius estimation, ${w} g of an organic compound gave ${m} g of Ag${X} (Ag = 108, ${X} = ${at}). Find the percentage of ${X === 'Cl' ? 'chlorine' : X === 'Br' ? 'bromine' : 'iodine'}.`, answer: +a.toFixed(2), tol: 0.1, unit: '%', w, m, at, mw,
        sol: `<p>Molar mass of Ag${X} = ${mw}. Mass of ${X} in ${m} g of Ag${X} = ${at}/${mw} &times; ${m} = ${(at / mw * m).toFixed(4)} g.</p><p>%${X} = ${(at / mw * m).toFixed(4)}/${w} &times; 100 = <b>${a.toFixed(2)} %</b>.</p>` };
    }, verify: (p) => p.m * p.at / p.mw / p.w * 100 },
  { id: 'go-g06', type: 'nat', level: 3, exams: EX[3], sub: 'Carius method (S or P)',
    make(rng) {
      const isS = rng() < 0.5; const w = pick(rng, 0.2, 0.5, 0.05), m = pick(rng, 0.2, 0.7, 0.01);
      const ppt = isS ? 'BaSO<sub>4</sub> (233)' : 'Mg<sub>2</sub>P<sub>2</sub>O<sub>7</sub> (222)'; const f = isS ? 32 / 233 : 62 / 222; const a = f * m / w * 100;
      return { q: `${w} g of an organic compound containing ${isS ? 'sulphur' : 'phosphorus'} gave ${m} g of ${ppt} after the usual treatment. Find the percentage of ${isS ? 'sulphur (S = 32)' : 'phosphorus (P = 31)'}.`, answer: +a.toFixed(2), tol: 0.1, unit: '%', isS, w, m,
        sol: isS ? `<p>One mole of BaSO<sub>4</sub> contains 1 mol S: 233 g has 32 g S.</p><p>%S = (32/233) &times; ${m}/${w} &times; 100 = <b>${a.toFixed(2)} %</b>.</p>` : `<p>One mole of Mg<sub>2</sub>P<sub>2</sub>O<sub>7</sub> (222 g) holds 2 mol P = 62 g.</p><p>%P = (62/222) &times; ${m}/${w} &times; 100 = <b>${a.toFixed(2)} %</b>.</p>` };
    }, verify: (p) => (p.isS ? 32 / 233 : 62 / 222) * p.m / p.w * 100 },
  { id: 'go-g07', type: 'nat', level: 3, exams: EX[3], sub: 'combustion analysis',
    make(rng) {
      const w = pick(rng, 0.2, 0.5, 0.05), co2 = pick(rng, 0.3, 0.9, 0.01), h2o = pick(rng, 0.1, 0.5, 0.01); const askC = rng() < 0.5;
      const a = askC ? 12 / 44 * co2 / w * 100 : 2 / 18 * h2o / w * 100;
      return { q: `Complete combustion of ${w} g of an organic compound gave ${co2} g of CO<sub>2</sub> and ${h2o} g of H<sub>2</sub>O. Find the percentage of ${askC ? 'carbon' : 'hydrogen'}.`, answer: +a.toFixed(2), tol: 0.1, unit: '%', w, co2, h2o, askC,
        sol: askC ? `<p>44 g of CO<sub>2</sub> contains 12 g C. Mass of C = 12/44 &times; ${co2} = ${(12 / 44 * co2).toFixed(4)} g.</p><p>%C = ${(12 / 44 * co2).toFixed(4)}/${w} &times; 100 = <b>${a.toFixed(2)} %</b>.</p>` : `<p>18 g of H<sub>2</sub>O contains 2 g H. Mass of H = 2/18 &times; ${h2o} = ${(2 / 18 * h2o).toFixed(4)} g.</p><p>%H = ${(2 / 18 * h2o).toFixed(4)}/${w} &times; 100 = <b>${a.toFixed(2)} %</b>.</p>` };
    }, verify: (p) => p.askC ? p.co2 / 44 * 12 / p.w * 100 : p.h2o / 18 * 2 / p.w * 100 },
  { id: 'go-g08', type: 'nat', level: 3, exams: EX[3], sub: 'molecular formula from composition',
    make(rng) {
      const [fm, x, y, z] = choose(rng, COMPOUNDS); const M = 12 * x + y + 16 * z; const pc = +(1200 * x / M).toFixed(1), ph = +(100 * y / M).toFixed(1);
      const what = choose(rng, ['C', 'H', 'O']); const ans = what === 'C' ? x : what === 'H' ? y : z;
      const nm = { C: 'carbon', H: 'hydrogen', O: 'oxygen' }[what]; const po = +(100 - pc - ph).toFixed(1);
      return { q: `An organic compound has ${pc} % carbon and ${ph} % hydrogen, the rest being oxygen, and a molar mass of ${M} g/mol. How many ${nm} atoms are in one molecule?`, answer: ans, tol: 0, x, y, z, M, pc, ph, what,
        sol: `<p>Atoms of C = ${M} &times; ${pc}/(100 &times; 12) = ${(M * pc / 1200).toFixed(2)} &asymp; ${x}. Atoms of H = ${M} &times; ${ph}/100 = ${(M * ph / 100).toFixed(2)} &asymp; ${y}. Oxygen is ${po} %: ${M} &times; ${po}/(100 &times; 16) = ${(M * po / 1600).toFixed(2)} &asymp; ${z}.</p><p>The formula is ${fm}, so ${nm} atoms: <b>${ans}</b>.</p>` };
    }, verify: (p) => { const c = Math.round(p.M * p.pc / 1200), h = Math.round(p.M * p.ph / 100), o = Math.round(p.M * (100 - p.pc - p.ph) / 1600); return p.what === 'C' ? c : p.what === 'H' ? h : o; } },
  { id: 'go-g09', type: 'nat', level: 2, exams: EX[2], sub: 'hyperconjugation',
    make(rng) {
      const [name, adj] = choose(rng, ALPHA);
      return { q: `The number of alpha-hydrogens (hyperconjugative structures) for ${name} is`, answer: adj.reduce((a, b) => a + b, 0), tol: 0, adj,
        sol: `<p>Count the hydrogens on carbons directly attached to the positive carbon (or to the double-bond carbon). Neighbouring carbons give ${adj.join(' + ')} = <b>${adj.reduce((a, b) => a + b, 0)}</b>.</p><p>The hydrogens on the cationic or double-bond carbon itself are not counted.</p>`, trap: 'Hydrogens on the cationic carbon do not count.' };
    }, verify: (p) => p.adj.reduce((a, b) => a + b, 0) },
  { id: 'go-g10', type: 'nat', level: 4, exams: EX[4], sub: 'counting stereoisomers',
    make(rng) {
      const n = int(rng, 2, 5); const geo = rng() < 0.5; const a = geo ? 2 ** (n - 1) + 2 ** (Math.ceil(n / 2) - 1) : (n % 2 === 0 ? 2 ** (n - 1) + 2 ** (n / 2 - 1) : 2 ** (n - 1));
      const fm = geo ? `CH<sub>3</sub>(CH=CH)<sub>${n}</sub>CH<sub>3</sub>` : `HOOC(CHOH)<sub>${n}</sub>COOH`;
      return { q: `The total number of ${geo ? 'geometrical isomers' : 'stereoisomers'} of ${fm} is`, answer: a, tol: 0, n, geo,
        sol: geo ? `<p>Each of the ${n} double bonds can be E or Z: 2<sup>${n}</sup> = ${2 ** n} combinations. The molecule is symmetric, so a combination and its end-to-end reversal are the same compound. Combinations that are their own reversal: 2<sup>${Math.ceil(n / 2)}</sup> = ${2 ** Math.ceil(n / 2)}.</p><p>Distinct = (${2 ** n} + ${2 ** Math.ceil(n / 2)})/2 = <b>${a}</b>.</p>` : `<p>${n} chiral centres in a symmetric chain. ${n % 2 === 0 ? `Even n: total = 2<sup>n&minus;1</sup> + 2<sup>n/2&minus;1</sup> = ${2 ** (n - 1)} + ${2 ** (n / 2 - 1)} = <b>${a}</b> (some are meso).` : `Odd n: total = 2<sup>n&minus;1</sup> = <b>${a}</b> (the middle centre is pseudo-asymmetric in the meso forms).`}</p>`, trap: 'Symmetry reduces the 2<sup>n</sup> count.' };
    }, verify: (p) => p.geo ? geoCount(p.n) : chiralCount(p.n) },
  { id: 'go-g11', type: 'nat', level: 3, exams: EX[3], sub: 'counting stereoisomers',
    make(rng) {
      const n = int(rng, 1, 4), m = int(rng, 1, 3);
      return { q: `A molecule with no symmetry has ${n} different chiral carbon${n > 1 ? 's' : ''} and ${m} unsymmetrical double bond${m > 1 ? 's' : ''} (each carbon of each double bond has two different groups). The total number of stereoisomers is`, answer: 2 ** (n + m), tol: 0, n, m,
        sol: `<p>Each chiral centre doubles the count (R or S) and each such double bond doubles it (E or Z). Total = 2<sup>${n}</sup> &times; 2<sup>${m}</sup> = 2<sup>${n + m}</sup> = <b>${2 ** (n + m)}</b>.</p>` };
    }, verify: (p) => (1 << p.n) * (1 << p.m) },
  { id: 'go-g12', type: 'nat', level: 2, exams: EX[2], sub: 'sigma and pi bonds',
    make(rng) {
      const n = int(rng, 3, 10), kind = choose(rng, ['alkane', 'alkene', 'alkyne', 'cycloalkane']);
      const nCH = { alkane: 2 * n + 2, alkene: 2 * n, alkyne: 2 * n - 2, cycloalkane: 2 * n }[kind]; const nCC = kind === 'cycloalkane' ? n : n - 1; const a = nCH + nCC;
      const fm = `C<sub>${n}</sub>H<sub>${nCH}</sub>`;
      const desc = { alkane: 'saturated acyclic', alkene: 'acyclic with one C=C', alkyne: 'acyclic with one C&equiv;C', cycloalkane: 'saturated monocyclic' }[kind];
      return { q: `The total number of sigma bonds in one molecule of the ${desc} hydrocarbon ${fm} is`, answer: a, tol: 0, nCH, nCC,
        sol: `<p>C&ndash;H bonds = ${nCH}. C&ndash;C sigma bonds = ${nCC} (${kind === 'cycloalkane' ? 'a ring of n carbons has n bonds' : 'n &minus; 1 bonds join the carbons in a chain; a double or triple bond still has just one sigma bond'}).</p><p>Total sigma = ${nCH} + ${nCC} = <b>${a}</b>.</p>` };
    }, verify: (p) => p.nCH + p.nCC },
  { id: 'go-g13', type: 'nat', level: 2, exams: EX[2], sub: 'chromatography',
    make(rng) {
      const f = choose(rng, RFLIST), s = pick(rng, 6, 12, 0.5), d = pick(rng, 1.5, 5.5, 0.1); const rf = d / s;
      return { q: `In thin-layer chromatography the solvent front moved ${s} cm and the ${f} moved ${d.toFixed(1)} cm from the baseline. Find its R<sub>f</sub> value.`, answer: +rf.toFixed(2), tol: 0.01, s, d,
        sol: `<p>R<sub>f</sub> = distance moved by substance / distance moved by solvent = ${d.toFixed(1)}/${s} = <b>${rf.toFixed(2)}</b>.</p><p>R<sub>f</sub> has no unit and is never above 1.</p>`, trap: 'R<sub>f</sub> cannot exceed 1.' };
    }, verify: (p) => p.d / p.s },
  { id: 'go-g14', type: 'nat', level: 4, exams: EX[4], sub: 'silver salt method',
    make(rng) {
      const [nm, M] = choose(rng, [['ethanoic acid', 60], ['propanoic acid', 74], ['butanoic acid', 88], ['benzoic acid', 122]]); const salt = M + 107; const ws = pick(rng, 0.5, 1.5, 0.1); const wag = +(ws * 108 / salt).toFixed(3);
      const ew = ws * 108 / wag - 107;
      return { q: `A monobasic organic acid forms a silver salt. Heating ${ws} g of the silver salt leaves ${wag} g of metallic silver (Ag = 108). Find the molar mass of the acid.`, answer: +ew.toFixed(1), tol: 2, unit: 'g/mol', ws, wag, M,
        sol: `<p>One mole of silver salt RCOOAg gives one mole of Ag (108 g). Molar mass of salt = ${ws} &times; 108/${wag} = ${(ws * 108 / wag).toFixed(1)} g/mol.</p><p>Acid molar mass = salt &minus; 108 + 1 = ${(ws * 108 / wag).toFixed(1)} &minus; 107 = <b>${ew.toFixed(1)}</b> g/mol (about ${M}, ${nm}).</p>`, trap: 'The acid is lighter than its salt by 107 (Ag replaces H).' };
    }, verify: (p) => p.ws * 108 / p.wag - 107 },
  { id: 'go-g15', type: 'mcq', level: 3, exams: EX[3], sub: 'IUPAC naming (alcohols)',
    make(rng) {
      let n, p, m, tries = 0;
      do { n = int(rng, 5, 8); p = int(rng, 2, n - 1); m = int(rng, 2, n - 1); tries++; } while ((p === m || 2 * p === n + 1 || 2 * (p <= n + 1 - p ? m : n + 1 - m) === n + 1) && tries < 200);
      const fwd = p <= n + 1 - p; const pp = fwd ? p : n + 1 - p, mm = fwd ? m : n + 1 - m; const st = STEM[n];
      const name = (a, b) => `${a}-methyl${st}an-${b}-ol`;
      const right = name(mm, pp);
      const { options, answer } = shuffleOpts(rng, right, [name(n + 1 - mm, n + 1 - pp), name(n + 1 - mm, pp), name(mm, n + 1 - pp)]);
      const txt = F(chainText(n, { [p]: 'OH', [m]: 'CH3' }));
      return { q: `The IUPAC name of ${txt} is`, options, answer, n, p, m, right,
        sol: `<p>The longest chain has ${n} carbons (${st}ane). The suffix -ol gets the lowest locant: counting from the nearer end, OH is on C${pp}. The methyl is then on C${mm}.</p><p>Name: <b>${right}</b>. The other options number from the wrong end for the OH, the methyl, or both.</p>`, trap: 'The principal group (OH) decides the direction of numbering, not the methyl.' };
    }, verify: (p) => { const a = Math.min(p.p, p.n + 1 - p.p); const mm = p.p <= p.n + 1 - p.p ? p.m : p.n + 1 - p.m; return p.options.indexOf(`${mm}-methyl${STEM[p.n]}an-${a}-ol`); } },
  { id: 'go-g16', type: 'mcq', level: 3, exams: EX[3], sub: 'IUPAC naming (alkenes)',
    make(rng) {
      let n, p, m, tries = 0;
      do { n = int(rng, 5, 8); p = int(rng, 1, n - 1); m = int(rng, 2, n - 1); tries++; } while ((2 * p === n || 2 * (p <= n - p ? m : n + 1 - m) === n + 1) && tries < 200);
      const fwd = p <= n - p; const pp = fwd ? p : n - p, mm = fwd ? m : n + 1 - m; const st = STEM[n];
      const name = (a, b) => `${a}-methyl${st}-${b}-ene`;
      const right = name(mm, pp);
      const { options, answer } = shuffleOpts(rng, right, [name(n + 1 - mm, n - pp), name(n + 1 - mm, pp), name(mm, n - pp)]);
      const txt = F(chainText(n, { [m]: 'CH3' }, p));
      return { q: `The IUPAC name of ${txt} is`, options, answer, n, p, m, right,
        sol: `<p>The parent chain is the longest chain containing the C=C: ${n} carbons (${st}ene). Number from the end nearer the double bond so it gets the lowest locant: C=C starts at C${pp}. The methyl is then on C${mm}.</p><p>Name: <b>${right}</b>.</p>`, trap: 'The double bond, not the branch, decides the numbering direction.' };
    }, verify: (p) => { const a = Math.min(p.p, p.n - p.p); const mm = p.p <= p.n - p.p ? p.m : p.n + 1 - p.m; return p.options.indexOf(`${mm}-methyl${STEM[p.n]}-${a}-ene`); } },
  { id: 'go-g17', type: 'mcq', level: 3, exams: EX[3], sub: 'IUPAC naming (rings)',
    make(rng) {
      const subs = [['bromo', 'Br'], ['chloro', 'Cl'], ['ethyl', 'C2H5'], ['methyl', 'CH3'], ['nitro', 'NO2'], ['propyl', 'C3H7']];
      const i = int(rng, 0, 4), j = int(rng, i + 1, 5); const [a, fa] = subs[i], [b, fb] = subs[j]; const ring = int(rng, 6, 8), k = int(rng, 2, 4);
      const flip = rng() < 0.5; const [x, y] = flip ? [b, a] : [a, b]; // x,y: order as drawn in the question
      const rel = k === 2 ? 'on adjacent carbons' : k === 3 ? 'on carbons with one carbon between them' : 'on carbons with two carbons between them';
      const right = `1-${a}-${k}-${b}${RING[ring]}`;
      const { options, answer } = shuffleOpts(rng, right, [`${k}-${a}-1-${b}${RING[ring]}`, `1-${b}-${k}-${a}${RING[ring]}`, `1-${a}-${k}-${b}${RING[ring - 1]}`]);
      return { q: `A ${RING[ring]} ring carries ${y} and ${x} groups ${rel}. Its IUPAC name is`, options, answer, a, b, ring, k, right,
        sol: `<p>Both numberings give the lowest locant set {1,${k}}, so the tie is broken alphabetically: <b>${a}</b> comes before <b>${b}</b>, so ${a} takes C1.</p><p>Name: <b>${right}</b>. The prefixes are cited alphabetically, and the ring is the parent because it is the larger part.</p>`, trap: 'Alphabetical order, not size or atomic number, decides which group is C1.' };
    }, verify: (p) => p.options.indexOf(`1-${p.a}-${p.k}-${p.b}${RING[p.ring]}`) },
];

